WITH target AS (SELECT tid FROM target_dictionary WHERE pref_name = 'Sialic acid-binding Ig-like lectin 9' AND tax_id = 9606 AND organism = 'Homo sapiens' AND target_type = 'PROTEIN'),
activity_compounds AS (SELECT DISTINCT a.molecule_chembl_id AS chembl_id, cs.canonical_smiles FROM activities a JOIN assays ass ON a.assay_id = ass.assay_id JOIN target_dictionary td ON ass.tid = td.tid JOIN molecule_dictionary md ON a.molecule_chembl_id = md.molregno JOIN compound_structures cs ON md.molregno = cs.molregno WHERE td.chembl_id = 'CHEMBL4105860' AND ass.assay_organism = 'Homo sapiens')
SELECT DISTINCT chembl_id, canonical_smiles FROM activity_compounds;
